export function contributionHtml(report,{esc,number,pct}={}){
 if(!report)return '<p class="inline-note">Sayısal oyuncu katkısı için etkin ve eğitilmiş GBDT modeli gerekli.</p>';
 const delta=v=>Number.isFinite(v)?(v>0?'+':'')+number(v,3):'—';
 return `<section class="player-contribution"><h3>Oyuncuların sayısal kadro katkısı</h3><p class="inline-note">Oyuncunun yerine aynı mevkiden aday oynatılır; diğer oyuncular ve takım girdileri sabit tutulur. Hücum katkısı = oyuncuyla gol beklentisi − adayla gol beklentisi. Savunma katkısı = adayla rakip gol beklentisi − oyuncuyla rakip gol beklentisi. Net katkı ikisinin toplamıdır. Eksi değer, modelin kıyas adayını daha güçlü bulduğunu gösterebilir. Katkılar H2H öncesi GBDT gol tabanında ölçülür.</p>${report.absenceImpact?`<p class="inline-note">Önceki ilk 11 tam kadroyken gol tabanı: <b>${number(report.healthyPreviousXI.home,2)} – ${number(report.healthyPreviousXI.away,2)}</b>. Eksikler ve aday yedeklerle: <b>${number(report.selectedMeans.home,2)} – ${number(report.selectedMeans.away,2)}</b>. Fark: <b>${delta(report.absenceImpact.home)} / ${delta(report.absenceImpact.away)}</b> beklenen gol. Bu etki zaten kadro girdilerindedir; ikinci kez eklenmez.</p>`:''}<details><summary>Her oyuncunun katkısı, kıyas adayı ve veri kapsamı</summary><div class="table-wrap"><table><thead><tr><th>OYUNCU</th><th>DURUM / KIYAS</th><th>HÜCUM ΔGOL</th><th>SAVUNMA ΔGOL</th><th>NET ΔGOL</th><th>GALİBİYET ΔYÜZDE PUAN</th><th>KAPSAM</th></tr></thead><tbody>${report.rows.map(p=>`<tr><td>${esc(p.name)}<small>${esc(p.teamName)}</small></td><td>${p.unavailable?'Sakat / eksik':p.historyOnly?'Eski kadro · varsayımsal':p.selected?'İlk 11':'Aday yedek'} · ${esc(p.comparisonPlayer??'Kıyas adayı yok')}<small>${esc(p.reason)}</small></td><td>${delta(p.ownGoalContribution)}</td><td>${delta(p.opponentGoalsAvoided)}</td><td>${delta(p.netGoalContribution)}</td><td>${Number.isFinite(p.winProbabilityDelta)?delta(p.winProbabilityDelta*100):'—'}</td><td>${p.games} maç / ${number(p.minutes,0)} dk</td></tr>`).join('')}</tbody></table></div></details><p class="inline-note">${esc(report.note)}</p></section>`;
}
